    solution: "// Exercise 33 - ATM Simulation with do...while menu\n\n// ---------- INPUT (menu choice, amount) ----------\nconst double startingBalance = 1000;\nconst List<List<double>> actions = [\n  [1, 500],   // deposit 500\n  [2, 200],   // withdraw 200\n  [2, 5000],  // withdraw too much -> failed\n  [1, -50],   // invalid deposit\n  [3, 0],     // check balance\n  [9, 0],     // invalid menu\n  [4, 0],     // exit\n];\n\nvoid main() {\n  double balance = startingBalance;\n  int deposits = 0;\n  int withdrawals = 0;\n  int failedWithdrawals = 0;\n  int step = 0;\n  int choice;\n\n  do {\n    print('===== ATM MENU =====');\n    print('1. Deposit');\n    print('2. Withdraw');\n    print('3. Check Balance');\n    print('4. Exit');\n\n    choice = actions[step][0].toInt();\n    final double amount = actions[step][1];\n    step++;\n    print('Choice: $choice');\n\n    switch (choice) {\n      case 1:\n        if (amount > 0) {\n          balance += amount;\n          deposits++;\n          print('Deposited \\$${amount.toStringAsFixed(2)}');\n        } else {\n          print('Error: deposit must be positive');\n        }\n        break;\n      case 2:\n        if (amount > balance) {\n          failedWithdrawals++;\n          print('Error: insufficient balance');\n        } else if (amount <= 0) {\n          failedWithdrawals++;\n          print('Error: withdrawal must be positive');\n        } else {\n          balance -= amount;\n          withdrawals++;\n          print('Withdrew \\$${amount.toStringAsFixed(2)}');\n        }\n        break;\n      case 3:\n        print('Balance: \\$${balance.toStringAsFixed(2)}');\n        break;\n      case 4:\n        print('Exiting...');\n        break;\n      default:\n        print('Error: invalid menu option');\n    }\n    print('');\n  } while (choice != 4 && step < actions.length);\n\n  print('===== SUMMARY =====');\n  print('Final Balance       : \\$${balance.toStringAsFixed(2)}');\n  print('Number of Deposits  : $deposits');\n  print('Number of Withdrawals: $withdrawals');\n  print('Failed Withdrawals  : $failedWithdrawals');\n}\n",
